def create_onnx_model_with_mixed_custom_domains(tmp_path: Path) -> Path:
    X = helper.make_tensor_value_info("input", TensorProto.FLOAT, [1])
    Z = helper.make_tensor_value_info("output", TensorProto.FLOAT, [1])
