    def test_referenced_onehot_axis_preserves_recurrence_shape(
        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch, referenced: bool, axis: int
    ) -> None:
        hot = helper.make_node("OneHot", ["indices", "depth", "values"], ["out"], axis=axis)
